//! Exact integer residual for the Pic2 translation correction, generated by monic reductions.
use crate::{identity_certificate as ic, round02};
use num_bigint::BigInt as Z;
use num_integer::Integer;
use num_traits::{One, ToPrimitive, Zero};
use serde_json::json;
use std::{collections::BTreeMap, path::Path};
type P = BTreeMap<[usize; 5], Z>;
fn c(n: i64) -> P {
    if n == 0 {
        P::new()
    } else {
        BTreeMap::from([([0; 5], Z::from(n))])
    }
}
fn var(i: usize) -> P {
    let mut m = [0; 5];
    m[i] = 1;
    BTreeMap::from([(m, Z::one())])
}
fn add(a: &P, b: &P) -> P {
    let mut q = a.clone();
    for (m, c) in b {
        let e = q.entry(*m).or_default();
        *e += c;
        if e.is_zero() {
            q.remove(m);
        }
    }
    assert!(q.len() <= 4096);
    q
}
fn mul(a: &P, b: &P) -> P {
    let mut q = P::new();
    for (m, x) in a {
        for (n, y) in b {
            let key = std::array::from_fn(|i| m[i] + n[i]);
            assert!(key.iter().sum::<usize>() <= 16);
            q = add(&q, &BTreeMap::from([(key, x * y)]));
        }
    }
    q
}
fn pow(p: &P, n: usize) -> P {
    (0..n).fold(c(1), |v, _| mul(&v, p))
}
fn neg(p: &P) -> P {
    p.iter().map(|(m, c)| (*m, -c)).collect()
}
fn sub(a: &P, b: &P) -> P {
    add(a, &neg(b))
}
fn sum(ps: &[P]) -> P {
    ps.iter().fold(P::new(), |a, b| add(&a, b))
}
fn reduce(mut p: P, g: &P, i: usize) -> (P, P) {
    let mut q = P::new();
    let mut ops = 0;
    while let Some((m, x)) = p
        .iter()
        .find(|(m, _)| m[i] >= 2)
        .map(|(m, c)| (*m, c.clone()))
    {
        let mut n = m;
        n[i] -= 2;
        let t = BTreeMap::from([(n, x)]);
        q = add(&q, &t);
        p = sub(&p, &mul(&t, g));
        ops += 1;
        assert!(ops < 100000);
    }
    (q, p)
}
fn lean(p: &P) -> String {
    if p.is_empty() {
        return "0".into();
    }
    p.iter()
        .map(|(m, c)| {
            let mut s = format!("({c}:R)");
            for (i, n) in m.iter().enumerate() {
                if *n > 0 {
                    s += &format!("*{}^{n}", ["x", "y", "s", "t", "a"][i]);
                }
            }
            s
        })
        .collect::<Vec<_>>()
        .join(" + ")
}
fn expr(p: &P) -> ic::Expr {
    ic::Expr::sum(
        p.iter()
            .map(|(m, c)| {
                ic::Expr::product(
                    std::iter::once(ic::Expr::Const(c.to_i64().unwrap()))
                        .chain(m.iter().enumerate().flat_map(|(i, n)| {
                            std::iter::repeat_n(ic::Expr::var(["x", "y", "s", "t", "a"][i]), *n)
                        }))
                        .collect(),
                )
            })
            .collect(),
    )
}
fn polynomials() -> (P, P, P, P, P, P) {
    let (x, y, s, t, a) = (var(0), var(1), var(2), var(3), var(4));
    let cy = sum(&[
        pow(&y, 2),
        mul(&x, &y),
        pow(&x, 3),
        mul(&a, &pow(&x, 2)),
        c(1),
    ]);
    let ct = sum(&[
        pow(&t, 2),
        mul(&s, &t),
        pow(&s, 3),
        mul(&a, &pow(&s, 2)),
        c(1),
    ]);
    let u = add(&x, &s);
    let n = sum(&[
        pow(&add(&y, &t), 2),
        mul(&add(&y, &t), &u),
        mul(&add(&u, &a), &pow(&u, 2)),
    ]);
    let d = sum(&[
        mul(&s, &y),
        mul(&sum(&[t.clone(), s.clone(), c(1)]), &x),
        s.clone(),
    ]);
    let r = sub(
        &mul(&n, &pow(&d, 2)),
        &mul(
            &mul(&s, &x),
            &mul(&pow(&add(&mul(&s, &x), &c(1)), 2), &pow(&u, 2)),
        ),
    );
    let (aa, p) = reduce(r.clone(), &cy, 1);
    let (bb, p) = reduce(p, &ct, 3);
    assert!(p.values().all(|c| c.is_even()));
    let cc = p.iter().map(|(m, c)| (*m, c / 2)).collect();
    assert_eq!(r, sum(&[mul(&aa, &cy), mul(&bb, &ct), mul(&c(2), &cc)]));
    (r, cy, ct, aa, bb, cc)
}
pub fn statement() -> ic::IdentityStatement {
    let (r, cy, ct, a, b, c0) = polynomials();
    ic::IdentityStatement {
        name: "Pic2-correction-square".into(),
        source: "KoblitzRound17LiftProof.correction_square_residual".into(),
        variables: ["x", "y", "s", "t", "a"].map(str::to_string).to_vec(),
        degree_bound: 16,
        lhs: expr(&r),
        rhs: expr(&sum(&[mul(&a, &cy), mul(&b, &ct), mul(&c(2), &c0)])),
    }
}
pub fn run(dir: &Path) {
    let (r, cy, ct, aa, bb, cc) = polynomials();
    let mut lean = String::from("import KoblitzRound17\nnamespace KoblitzRound17LiftProof\n");
    for (name, p) in [("A", &aa), ("B", &bb), ("C", &cc)] {
        lean.push_str(&format!(
            "def {name} {{R:Type*}} [CommRing R] (x y s t a:R) : R := {}\n",
            self::lean(p)
        ));
    }
    lean.push_str("theorem correction_square_residual {R:Type*} [CommRing R] (x y s t a:R) :\n ((y+t)^2+(y+t)*(x+s)+(x+s+a)*(x+s)^2)*(s*y+(t+s+1)*x+s)^2-s*x*(s*x+1)^2*(x+s)^2=\n A x y s t a*(y^2+x*y+x^3+a*x^2+1)+B x y s t a*(t^2+s*t+s^3+a*s^2+1)+2*C x y s t a := by\n unfold A B C\n ring\n");
    lean.push_str("theorem correction_square_cleared {R:Type*} [CommRing R] [CharP R 2]\n (x y s t a:R) (hp:y^2+x*y+x^3+a*x^2+1=0) (hq:t^2+s*t+s^3+a*s^2+1=0) :\n ((y+t)^2+(y+t)*(x+s)+(x+s+a)*(x+s)^2)*(s*y+(t+s+1)*x+s)^2=s*x*(s*x+1)^2*(x+s)^2 := by\n have h:=correction_square_residual x y s t a\n have h2:(2:R)=0:=CharP.cast_eq_zero R 2\n rw [hp,hq,h2] at h\n simpa using sub_eq_zero.mp (by simpa using h)\n");
    lean.push_str("theorem correction_square_rational {R:Type*} [Field R] [CharP R 2]\n (x y s t a:R) (hp:y^2+x*y+x^3+a*x^2+1=0) (hq:t^2+s*t+s^3+a*s^2+1=0)\n (hu:x+s≠0) (hd:s*y+(t+s+1)*x+s≠0) :\n ((y+t)^2+(y+t)*(x+s)+(x+s+a)*(x+s)^2)/(x+s)^2=\n s*x*((s*x+1)/(s*y+(t+s+1)*x+s))^2 := by\n have h:=correction_square_cleared x y s t a hp hq\n rw [div_pow, ←mul_div_assoc]\n exact (div_eq_div_iff (pow_ne_zero 2 hu) (pow_ne_zero 2 hd)).2 h\n");
    lean.push_str("theorem CM_norm_product {R:Type*} [CommRing R] (a b c d:R) :\n (a*c-2*b*d)^2-(a*c-2*b*d)*(a*d+b*c-b*d)+2*(a*d+b*c-b*d)^2=\n (a^2-a*b+2*b^2)*(c^2-c*d+2*d^2) := by ring\nend KoblitzRound17LiftProof\n");
    for n in [
        "correction_square_residual",
        "correction_square_cleared",
        "correction_square_rational",
        "CM_norm_product",
    ] {
        lean.push_str(&format!("#print axioms KoblitzRound17LiftProof.{n}\n"));
    }
    let p = dir.join("KoblitzRound17LiftProof.lean");
    assert!(!p.exists());
    std::fs::write(p, lean).unwrap();
    let val = |p: &P| {
        p.iter()
            .map(|(m, c)| json!({"exponents":m,"coefficient":c.to_string()}))
            .collect::<Vec<_>>()
    };
    round02::save(
        dir,
        "g18-Pic2-correction-square-residual.json",
        &json!({"schema":"koblitz.round17/g18-proof-v1","variables":["x","y","s","t","a"],"residual":val(&r),"curve_P":val(&cy),"curve_Q":val(&ct),"cofactors":[val(&aa),val(&bb),val(&cc)],"integer_identity_verified":true}),
    );
}
